import json, os, urllib.parse, urllib.request
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
tool='toolshed.g2.bx.psu.edu/repos/iuc/hisat2/hisat2/2.2.3+galaxy0'
url=os.environ['GALAXY_URL']+'/api/tools/'+urllib.parse.quote(tool,safe='')+'/build?history_id=bbd44e69cb8906b5aedbd8d2ea3b1ce1'
req=urllib.request.Request(url,headers={'x-api-key':key})
obj=json.load(urllib.request.urlopen(req))

def walk(x,path=''):
    if isinstance(x,dict):
        name=x.get('name')
        p=f'{path}|{name}' if name else path
        if name=='index':
            for o in x.get('options',[]):
                if any(k in str(o).lower() for k in ('human','hg38','grch38')): print(o)
        for k,v in x.items():
            if k not in ('options',): walk(v,p)
    elif isinstance(x,list):
        for v in x: walk(v,path)
walk(obj)
